#include <iostream>
#include <vector>
std::vector<std::vector<int>> g{{1}, {0, 2}, {1, 0}};
std::vector<bool> vis(3, false);
void dfs(int u) {
    vis[u] = true;
    for (int v : g[u]) if (!vis[v]) dfs(v);
}
int main() {
    dfs(0);
    std::cout << vis[0] << vis[1] << vis[2];
}

