#include <iostream>
#include <queue>
int main() {
    int g[4][2] = {{1, 2}, {0, 3}, {0, 3}, {1, 2}};
    bool vis[4] = {}; std::queue<int> q;
    q.push(0); vis[0] = true;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        std::cout << u;
        for (int v : g[u]) if (!vis[v]) { vis[v] = true; q.push(v); }
    }
}
